(1, 'Archies', 'Explore historical documentation, intergovernmental agreements, and decades of archival reports.', '', 'Self-paced learning on drug prevention, treatment, and recovery curricula — open to professionals, practitioners, and anyone.', 'DAP e-learning platform', 'archives', 1, '/uploads/ea635cf5-ef99-41cb-9c71-3d83867cf09a_1.jpg', 'Access archival records for research purposes'),
(2, 'E-Learning', 'Self-paced learning on drug prevention, treatment, and recovery curricula — open to professionals, practitioners, and anyone.', '', 'Self-paced learning on drug prevention, treatment, and recovery curricula — open to professionals, practitioners, and anyone.', 'DAP e-learning platform', 'courses', 0, '/uploads/641afdd4-7fe4-4baa-bb8b-8b62aeada038_2.jpg', 'Browse Courses');
INSERT IGNORE INTO `member_portal_items` (`id`, `badge`, `bullet_points`, `description`, `link_url`, `page_description`, `page_tag`, `page_title`, `slug`, `sort_order`, `thumbnail_url`, `title`) VALUES
(1, 'PUBLIC RESOURCE', 'Upcoming regional workshops & schedules\nParticipant certification archives\nExpert-led instructional modules', 'Explore upcoming capacity-building workshops, professional short courses, and specialized technical modules. View recently concluded sessions along with certified participant names and institutional profiles.', '', 'Access exclusive regional development resources, specialized training programmes, long-term scholarship archives, and official committee documentation designed to empower sovereign member states across Asia and the Pacific.', 'REGIONAL COOPERATION & DEVELOPMENT HUB', 'Member Countries Portal', 'training-opportunities', 0, '/uploads/aa2d355e-c1d5-4f28-a972-bae5036f7b49_1.jpg', 'Training Opportunities'),
(2, 'PUBLIC RESOURCE', 'Master\'s & doctoral degree opportunities\nApplication guidelines & criteria\nDirectory of alumni & past awardees', 'Discover full-funding academic scholarships, postgraduate programs, and fellowship grants offered in collaboration with premier regional universities. Browse past awardees and institutional success records.', '', 'Access exclusive regional development resources, specialized training programmes, long-term scholarship archives, and official committee documentation designed to empower sovereign member states across Asia and the Pacific.', 'REGIONAL COOPERATION & DEVELOPMENT HUB', 'Member Countries Portal', 'long-term-scholarships', 1, '/uploads/2ec7e3da-be75-4880-b66a-074d5f84ad00_2.jpg', 'Long-Term Scholarships'),
(3, 'MEMBERS ONLY', 'Quarterly council proceedings & minutes\nConfidential policy review documents\nMember state delegate archives', 'Restricted portal for official delegates. Access meeting agendas, working documents, executive decisions, and policy records of the Consultative Committee (CCM) and Executive Committee (EPG).', '', 'Access exclusive regional development resources, specialized training programmes, long-term scholarship archives, and official committee documentation designed to empower sovereign member states across Asia and the Pacific.', 'REGIONAL COOPERATION & DEVELOPMENT HUB', 'Member Countries Portal', 'council-standing-committee-meetings', 2, '/uploads/5b1bf0ff-c15c-400a-9256-a631072ae829_3.jpg', 'Council & Standing Committee Meetings');
