(5, 'Secretariat', 'Event', '', 'Regional delegates and health specialists convened to present updated evidence-based prevention toolkits and cross-border cooperation frameworks.', '', '', '/uploads/92015749-15dd-4fb1-a17b-1baed8dcc27c_Annual_Capacity.jpg', '', '2026-09-12', 'annual-capacity-building-drug-advisory-summit', 'Published', 'Annual Capacity Building & Drug Advisory Summit', '', ''),
(6, 'Secretariat', 'News', '', 'The Colombo Plan Secretariat published comprehensive statistical reviews detailing human resource investments across 26 member countries.', '', '', '/uploads/41eb5f5c-458c-4005-9820-293291822361_Publication_Release.jpg', '', '2026-09-03', 'publication-release-2026-south-south-cooperation-index', 'Published', 'Publication Release: 2026 South-South Cooperation Index', '', ''),
(7, 'Secretariat', 'News', '', 'Official launch of digital skill accreditation courses for young professionals and civil society leaders across the Asia-Pacific region.', '', '', '/uploads/5c59376d-6f69-4455-ba9f-7c1a6943246a_Youth_and_Gender.jpg', '', '2026-09-18', 'youth-gender-empowerment-initiative-launch', 'Published', 'Youth & Gender Empowerment Initiative Launch', '', '');
INSERT IGNORE INTO `private_sector_content` (`id`, `csr_partnerships`, `description`, `focal_point`, `region_tag`, `slug`, `thumbnail_url`, `title`, `what_we_offer`) VALUES
(3, 'Independent, delivery-focused implementation', 'Workforce upskilling, partnerships and CSR opportunities', 'Pulsara G', '', 'private-sector', '', 'PRIVATE SECTOR', 'Global Network of Trainers — certified specialists across partner countries\nEvidence-Based Prevention Curricula — workplace, youth, community, family\nWomen, Youth & Community Programmes — empowerment and inclusive capacity building\nCorporate Prevention Programmes — tailored substance use risk management for workforces\nAfrican Network Partnerships — expanding collaborative prevention frameworks across Africa\nDigital Prevention & E-Learning Modules — accessible online training platforms for remote stakeholder capacity building');
INSERT IGNORE INTO `programs` (`id`, `description`, `image_url`, `title`, `category_badge`, `established_info`, `feature_cards_json`, `feature_section_title`, `full_description`, `hero_image_url`, `impact_badges_json`, `impact_description`, `impact_title`, `portal_button_text`, `portal_url`, `short_code`, `slug`, `brochure_url`, `initiatives_json`, `initiatives_section_title`, `partnership_label`, `partnership_stats_json`, `partnership_title`, `theme_color`) VALUES
(5, 'Pioneering regional efforts in evidence-based substance use prevention, treatment practitioner certifications, and community recovery networks active across 80+ countries globally. Established in 1973, setting international standards through the Universal Treatment Curriculum (UTC).', '/uploads/e2f28d65-626d-4ca1-aec3-6cd17f9d8af9_DAP.jpg', 'Drug Advisory Programme (DAP)', 'Flagship Programme', '', '[{\"title\":\"Curricula Development & Training\",\"description\":\"Developing and implementing the Universal Treatment Curriculum (UTC) for addiction professionals to set high international standards in counselling and treatment.\"},{\"title\":\"Curriculum-Based Training\",\"description\":\"Conducting specialized training cycles for regional practitioners, law enforcement, and healthcare workers to manage substance use prevention effectively.\"},{\"title\":\"Donor-Directed Special Interventions\",\"description\":\"Executing targeted projects funded by international partners focusing on vulnerable communities, youth protection, and gender-responsive care.\"},{\"title\":\"Accreditation of Training Providers\",\"description\":\"Verifying and certifying regional training institutions and professionals through rigorous credentialing boards to maintain global quality benchmarks.\"}]', 'Drug Demand Reduction (DDR)', 'Established in 1973, DAP is the Colombo Plan\'s premier flagship initiative. It sets international standards for addiction treatment professionals through the Universal Treatment Curriculum (UTC) and supports national policy frameworks.', '/uploads/c9cc4b6c-ef81-4505-ae31-1e2609b1c3b6_DAP.JPG', '[]', 'Through decades of commitment, DAP has successfully certified thousands of addiction treatment and prevention professionals across Asia, Africa, and the Americas. By introducing standardized curricula and fostering regional peer networks, DAP continues to lead global efforts in mitigating substance use disorders.', 'Global Impact & Professional Standards', '', '', 'DAP', 'drug-advisory-programme-dap', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6, 'Advancing human resource development through specialized technical training, professional certifications, and prestigious master’s degree scholarships for member state officials, bridging critical public and private sector skill gaps.', '/uploads/3290e2e5-86dc-4e84-a3dc-4854c90497ff_CBP.jpg', 'Capacity Building Programme (CBP)', 'EDUCATION & SKILLS', 'CAPACITY BUILDING & SCHOLARSHIPS', '[{\"title\":\"Public Administration & Governance\",\"description\":\"Empowering civil servants, policymakers, and public sector administrators with advanced governance models, transparency frameworks, and policy implementation strategies.\"},{\"title\":\"Master\'s Degree Scholarships\",\"description\":\"Offering fully funded long-term postgraduate scholarships in partnership with top-tier universities across member nations to cultivate future regional leaders.\"},{\"title\":\"TVET & Technical Upskilling\",\"description\":\"Bridging industrial skill gaps through Technical and Vocational Education and Training (TVET) modules tailored for modern technological demands.\"},{\"title\":\"South-South Knowledge Exchange\",\"description\":\"Facilitating cross-border peer learning, expert delegations, and sharing best practices among developing member economies.\"}]', 'Strategic Priorities & Focus Areas', 'Focuses on bridging public sector skill gaps, fostering administrative excellence, and offering long-term academic scholarships in partnership with top-tier regional universities and institutions.', '/uploads/87cc704a-e748-4d7b-b66c-c7a2c01f5b99_CBP.jpg', '[]', 'CBP nominations are channeled directly through national focal points and government ministries of member states. Selected candidates undergo rigorous training modules, gaining internationally recognized certifications and practical expertise to implement institutional reforms upon return.', 'Programme Impact & Nomination Guidelines', '', '', 'CBP', 'capacity-building-programme-cbp', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7, 'Promoting sustainable green growth, renewable energy adoption, climate resilience projects, and green economy policies across vulnerable Asia-Pacific regions, supporting environmental ministries and carbon footprint mitigation.', '/uploads/adc12c11-f42c-45fc-b4cd-7b280df39330_CPECC.jpg', 'Environment & Climate Change (CPECC)', 'SUSTAINABILITY', 'CLIMATE ADAPTATION & GREEN ECONOMY', '[{\"title\":\"Solid Waste & Plastic Management\",\"description\":\"Promoting circular economy solutions, municipal waste reduction frameworks, and advanced recycling technologies across developing urban centers in the region.\"},{\"title\":\"Renewable Energy & Clean Tech\",\"description\":\"Capacity building on solar, wind, and geothermal adoption, supporting national grids in transitioning away from fossil fuel dependencies.\"},{\"title\":\"Sustainable Eco-Tourism\",\"description\":\"Developing nature-positive tourism standards that empower local indigenous communities while conserving fragile forest and coastal ecosystems.\"},{\"title\":\"Climate Resilience & Adaptation\",\"description\":\"Disaster risk mitigation training, early-warning system integration, and community-driven adaptation policies for vulnerable island and coastal states.\"}]', 'Strategic Priorities & Focus Areas', 'Aids developing member countries in formulating climate adaptation strategies, mitigating environmental degradation, and sharing green technology best practices through South-South cooperation.', '/uploads/6fb23164-4675-4d56-be23-e4fdc0d25446_ASEAN Biodiversity Center Collaboration.jpg', '[]', 'CPECC aligns its regional agendas directly with UN Sustainable Development Goals (SDGs 7, 13, and 15), facilitating cross-border partnerships that protect biodiversity and accelerate clean energy transitions.', 'Commitment to Sustainable Development Goals (SDGs)', '', '', 'CPECC', 'environment-climate-change-cpecc', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8, 'Strengthening maritime safety, port infrastructure development, technical advisory, and regional logistics cooperation across strategic shipping corridors through active pilot initiatives with regional port authorities.', '/uploads/516ea7a5-cfca-4c78-bf92-5a9e9617fbbb_MAP.jpg', 'Maritime Advisory Programme (MAP)', 'LOGISTICS & SAFETY', 'MARITIME SECURITY & TRADE', '[{\"title\":\"SLPA Capacity Building\",\"description\":\"Technical advisory visits, specialized port personnel training, and global best-practice knowledge exchange frameworks.\"},{\"title\":\"Digital Port Transformation\",\"description\":\"Advancing maritime cybersecurity, workforce digital readiness, IoT port connectivity, and paperless logistics systems.\"},{\"title\":\"Port Security & Safety\",\"description\":\"Enhancing ISPS compliance, physical container terminal security protocols, and marine emergency response protocols.\"},{\"title\":\"Regional Logistics Connectivity\",\"description\":\"Strengthening Indian Ocean transshipment networks and sustainable green shipping corridor initiatives.\"}]', 'Current Focus Areas & Pillars', 'Addresses vital maritime security challenges, enhances regulatory compliance for port management, and facilitates seamless cross-border maritime trade frameworks among coastal member states.', '/uploads/aa6e24e5-accf-4fab-b93f-607443b6d6df_MAP.jpg', '[]', 'MAP aims to establish standardized benchmarks for port administration across the Asia-Pacific. By fusing technical advisory with cutting-edge cybersecurity and sustainable green logistics, MAP ensures that participating ports remain resilient against future global supply chain disruptions.', 'Long-Term Regional Maritime Objectives', '', '', 'MAP', 'maritime-advisory-programme-map', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
